mapper.select:
SELECT title, content, cover_image, bar_id, id AS postId,
       (like_count * 5 + view_count * 2 + comment_count * 3) AS hotScore
FROM post

    deleted = 0

        AND (
            (like_count * 5 + view_count * 2 + comment_count * 3) < #{cursor.score}
            OR ((like_count * 5 + view_count * 2 + comment_count * 3) = #{cursor.score} AND id < #{cursor.postId})
        )


ORDER BY (like_count * 5 + view_count * 2 + comment_count * 3) DESC, id DESC
LIMIT #{pageSize}
